(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hu"] = {"ui":{"skip":"Ugrás a tartalomra","back":"← Vissza az AI-gile-hoz","lang.button":"Nyelv: {name}","lang.dialog":"Válassz nyelvet","lang.search":"Nyelvek keresése","lang.none":"Nincs találat","lang.notYet":"A(z) {name} még nincs lefordítva","theme.aria":"Váltás a világos és a sötét téma között","theme.toLight":"Váltás világos témára","theme.toDark":"Váltás sötét témára","index.title":"AI-gile: az MI-fejlesztőcsapatod, egyetlen táblán","index.description":"Az AI-gile egy kanbantábla MI-s programozócsapatoknak. Ők dolgoznak, amíg te alszol; neked egyetlen rövid halom marad: amit el kell döntened, ki kell próbálnod és el kell fogadnod.","hero.logoAlt":"Az AI-gile tábla ikonja","hero.h1.html":"Az MI-fejlesztőcsapatod, egyetlen&nbsp;táblán.","hero.alpha":"🐣 Zárt pre-alfa","hero.alphaTitle":"Korai és befejezetlen: köszi, hogy kipróbálod!","hero.lede":"Ők építenek, amíg te alszol. Te egyetlen rövid halomra ébredsz: pár kérdés, pár kipróbálnivaló, egy-két lila gyémánt. Kattintasz, elfogadod, és mehetsz vissza a kávédhoz.","dl.windows":"Windows-alkalmazás","dl.browser":"Futtasd a böngészőben","dl.soon":"Hamarosan","dl.notify":"🔔 Szólj, ha megnyílik","dl.notifySmall":"Alfa vagy béta","hero.secondary":"Agilis, de a csapatnak nincs szüksége stand-up kávéra. (Stand-upot azért tartanak.)","pitch.h2":"AI-gile annyi szóban, amennyit csak szeretnél","pitch.lede":"Válassz hosszt, egy szótól 144-ig. Minden hossznak saját leírása van, éppen arra a méretre írva. Húzd a csúszkát, vagy használd a nyílbillentyűket.","pitch.rangeLabel":"Hossz szavakban","pitch.dice":"🎲 másik változat","pitch.words.one":"{n} szó","pitch.words.other":"{n} szó","pitch.letters.one":"{n} betű","pitch.letters.other":"{n} betű","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kártya van most a táblán","count.line.html.other":"{n} kártya van most a táblán","features.aria":"Mit tud","f.pile.h":"Egyetlen halom neked","f.pile.html":"A <b>Neked</b> oszlopban van minden, ami rád vár, az összes projektből: kérdések, kipróbálnivalók, olyan feladatok, amiket csak ember végezhet el. A sorod megmondja, mi jön és mennyi ideig tart.","f.sleep.h":"Csapatok, amelyek dolgoznak, amíg alszol","f.sleep.p":"Minden projektnek van egy lead-je és egy MI-ügynökökből álló csapata. Írj megjegyzést egy kártyához, a csapat felébred, elvégzi a munkát, és olyan lépésekkel adja vissza, amelyeket egy fáradt ember is követni tud.","f.tester.h":"Előbb egy MI-tesztelő ellenőrzi","f.tester.p":"Mielőtt bármi eljutna hozzád, a tesztelő az alkalmazás egy másolatában végigköveti a lépéseket, és képernyőképpel megmutatja, mit látott. Lapozd át az átment kártyákat, és fogadd el őket egy kattintással.","f.proof.h":"Bizonyíték, nem ígéret","f.proof.p":"Minden átadás megmutatja, mi változott: a fájlokat, a diffet, a képernyőképeket. Nem kell minden alkalmazást megnyitnod, hogy kiderüljön, kész van-e.","f.chat.h":"Beszélgess a lead-jeiddel","f.chat.p":"Discord-stílusú oldalsáv: projektenként egy ikon, lila gyémántok arra, ami téged vár. Küldj egy ötletet a lead-nek; ő kártyákká és tervvé alakítja, egy ✅ Go gombbal.","f.tidy.h":"Magától rendben tartja magát","f.tidy.p":"Az összetartozó kártyák eggyé olvadnak, a zavaros címek kijavulnak, a tokenellenőrzés pedig karcsún tartja a kódot. Kevesebb váltogatás, kevesebb gondolkodnivaló.","f.private.h":"A tiéd, a te gépeden","f.private.li1":"A tábla a saját gépeden fut, és csak neked válaszol.","f.private.li2":"Az emberek közti privát üzenetek végponttól végpontig titkosítottak.","f.private.li3":"Nincs fiók, nincs követő, nincs süti.","f.lang.h":"A te nyelveden","f.lang.p":"Több mint 120 nyelv, a hollandtól, a walestől és a japántól a kalózig, Yodáig és klingonig, gyors visszaváltással angolra a fejlesztői szavakhoz.","tl.aria":"Idővonal az első beszélgetéstől az útitervig","tl.h2":"Az első beszélgetéstől a következő lépésekig","tl.lede":"Valódi dátumok és időpontok, a saját időzónádban. A mai nap után már csak a terv van, ígért dátumok nélkül.","tl.today":"Ma","tl.planned":"tervezett","tl.cards.one":"{n} kártya","tl.cards.other":"{n} kártya","join.h2":"Csatlakozz","join.lede":"Az AI-gile-t egy kis ember és sok türelmes ügynök építi. Egyelőre privát, zárt alfa a barátokkal. Szívesen kipróbálnád, ha megnyílik?","join.btn":"Érdeklődöm","join.small":"Írunk neked e-mailt, semmi mást","footer.tag":"AI-gile. Nincs követő, nincs süti, nincs stand-up kávé.","footer.licence":"Üzleti licenc","footer.status":"Állapot","form.sending":"Küldés…","form.failed":"Ez nem sikerült: próbáld újra később.","form.offline":"Nem érem el az AI-gile-t: próbáld újra később.","interest.title":"AI-gile: szólj, ha megnyílik az alfa","interest.description":"Hagyd meg az e-mail-címedet, és megtudod, mikor nyílik meg az AI-gile zárt alfája vagy bétája.","interest.h1":"🔔 Szólj, ha megnyílik","interest.lede":"Az AI-gile zárt pre-alfában van. Hagyd meg az e-mail-címedet, és egyszer írunk, amikor lesz hely számodra.","interest.email":"Az e-mail-címed","interest.which":"Melyik teszt?","interest.alpha":"Zárt alfa: korai, nyers, sok változás","interest.beta":"Béta: stabilabb, később","interest.both":"Bármelyik, amelyik előbb jön","interest.submit":"Tegyetek fel a listára","interest.thanks":"Köszi! Felkerültél a listára.","licence.title":"AI-gile: üzleti licenc","licence.description":"A vállalkozásodban használnád az AI-gile-t? Kérj ingyenes üzleti licencet.","licence.h1":"📜 Üzleti licenc","licence.lede":"Munkahelyen használnád az AI-gile-t? Mondd el, kik vagytok és mivel foglalkoztok. Ha jót tesz a világnak, a licenc ingyenes.","licence.company":"Cég","licence.website":"Weboldal","licence.what":"Mivel foglalkoztok","licence.how":"Hogyan segít ez a világnak","licence.email":"E-mail","licence.submit":"Jelentkezem","licence.thanks":"Köszi! E-mailben válaszolunk.","status.title":"Az AI-gile állapota","status.h1":"Az AI-gile állapota","status.quiet":"Minden csendes","status.checking":"Ellenőrzés…","status.offline":"Az állapotszolgáltatás most nem érhető el (újrapróbálom)","status.updated":"frissítve: {ago}","status.justNow":"épp most","status.min":"{n} perce","status.hours":"{n} órája","status.days":"{n} napja","live.h2":"Nézd, ahogy épül, élőben","live.caption":"Minden kártya rejtett: a munka alakját látod, nem a szavakat.","live.watching.one":"élő: {n} nézi","live.watching.other":"élő: {n} nézi","live.offline":"Az élő tábla kicsit pihen. Nézz vissza hamarosan.","live.cols":"Backlog|Teendő|Folyamatban|A csapat ellenőrzi|Neked kell tesztelni|A csapatnak|Kész","live.last.now":"Az utolsó kártya épp most mozdult","live.last.min.one":"Az utolsó kártya {n} perce mozdult","live.last.min.other":"Az utolsó kártya {n} perce mozdult","live.last.hour.one":"Az utolsó kártya {n} órája mozdult","live.last.hour.other":"Az utolsó kártya {n} órája mozdult","live.last.day.one":"Az utolsó kártya {n} napja mozdult","live.last.day.other":"Az utolsó kártya {n} napja mozdult"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotok.","Delegálva."]},{"n":2,"texts":["Robot kanban.","Rendezett ügynökök.","Ötletekből valóság."]},{"n":3,"texts":["Kanban robotoknak.","Ötletből funkció lesz.","Ingyenes ügynök-kanban."]},{"n":5,"texts":["Ügynökök által vezetett kanban tábla.","Te írod a kártyákat. Ők építenek.","Ingyenes, helyi, tesztelt, kicsit bolond."]},{"n":8,"texts":["Ingyenes kanban tábla, ahol az MI-ügynökök dolgoznak helyetted.","Leírsz egy ötletet. Az ügynökök megépítik. Te elfogadod.","Agilis munka egy embernek és sok türelmes robotnak."]},{"n":13,"texts":["Kanbantábla a gépeden, ahonnan az MI-ügynökök maguk viszik el a kártyákat.","Írj le egy ötletet. Ügynökök csapata megépíti. Egy tesztelő ellenőrzi.","Ingyenes, fiók és követés nélkül: egy tábla, néhány robot, és te irányítasz."]},{"n":21,"texts":["Az AI-gile egy kanbantábla az MI-s programozóügynökökkel való munkához. Ők viszik a kártyákat; te kipróbálod és elfogadod őket.","Minden projekt kap egy lead-et és egy MI-ügynökcsapatot. Írj megjegyzést bármelyik kártyához, és a csapat máris munkához lát.","Ingyenes, személyes teendőtábla, ami a saját gépeden fut. A dolgozók robotok. Aki igent mond, az te vagy."]},{"n":34,"texts":["Ötleteket teszel egy táblára. MI-ügynökök csapata működő funkciókká alakítja őket, kipróbálja, majd kipróbálható lépésekkel adja vissza neked. Semmi sem számít késznek, amíg te ezt ki nem mondod.","Az AI-gile egy házilag készült kanbantábla, amit Rich épített, rengeteg segítséggel azoktól az ügynököktől, akiket most irányít. Ingyenes, a gépeden fut, és barátokkal osztjuk meg, nem eladó.","Képzelj el egy hétköznapi kanbantáblát a Backlogtól a Kész oszlopig, csakhogy a kártyákat MI-ügynökök viszik. Beszámolnak az állásról, megkérdezik, ha elakadnak, és mindig megvárják a hüvelykujjadat felfelé."]},{"n":55,"texts":["Az AI-gile egy kanbantábla, amelynek csapata MI-ügynökökből áll. Minden projektnek van lead-je, aki megtervezi a munkát, és segítői, akik megépítik. Ha egy funkció elkészült, egy MI-tesztelő kipróbálja és képernyőképet készít, aztán a halmodra kerül. Fogadd el, vagy írj megjegyzést, és átdolgozzák. Nem kell közben mellettük állnod.","Úgy indult, hogy valaki egyszerre sok MI-programozós munkamenetet akart követni, aztán rendes táblává nőtte ki magát. A gépeden fut, nem kér fiókot, és nincsenek benne követők. Ingyenes barátoknak és bárkinek, akit érdekel. Befejezetlen is, úgyhogy számíts éles szélekre és egy-egy meglepetésre. Cserébe a tiéd, és nyugodtan alakíthatod.","Íme az őszinte változat. Az ötleteket továbbra is neked kell kitalálnod, az eredményt pedig neked kell ellenőrizned. Az AI-gile mindent csinál a kettő között: sorban tartja a kártyákat, a megfelelő ügynököt költi fel, ha megjegyzést írsz, pontosan megmutatja, mi változott, és mindezt egyetlen rövid halomba gyűjti neked."]},{"n":89,"texts":["Az AI-gile egy ingyenes kanbantábla, amit a saját gépeden futtatsz. Emberek helyett minden projektnek egy MI-ügynökcsapata van: egy lead, aki az ötleteidből kártyákat és tervet csinál, és segítők, akik prioritási sorrendben viszik a kártyákat. Ha elkészül valami, egy MI-tesztelő végigköveti a tesztlépéseket, és megmutatja, mit látott. Aztán az egész egy Neked nevű halomban vár. Elfogadod, vagy megjegyzést írsz, és a csapat újra nekifut. Semmi sem jut a Kész oszlopba nálad nélkül.","Néhány dolog, amire talán nem számítasz. Az éjjeliőr feltölti a Teendő oszlopot, amíg alszol, olyan kártyákat választva, amelyekhez nem kell a válaszod. A tokenszámláló megmutatja, mennyit használtak az ügynökök ma és ezen a héten, a Token nélküli mód pedig leállítja a költekezést. Üzenhetsz a barátaidnak, a privát üzenetek végponttól végpontig titkosítottak. A tábla nagyjából 120 nyelven beszél, köztük hollandul, flamandul, kalózul és klingonul. Mindez egy fillérbe sem kerül, és senki nem akarja rád sózni.","Az AI-gile egy kis személyes projekt, nem cég. Rich több MI-s programozási projektre akart vigyázni anélkül, hogy minden alkalmazást megnyitna, így az ügynökökkel építettek egy táblát, majd azzal a táblával építették meg önmaguk többi részét. Zárt pre-alfában van, vagyis többé-kevésbé működik egy maroknyi barátnak. Nincs árlap, nincs hírlevél, nincs növekedési terv. Nincs mögötte nagy terv, csak egy ember és egy csapat türelmes ügynök, akik élvezik a munkát. Ha hasznosnak hangzik, kérheted, hogy kipróbálhasd, amikor egy kicsit szélesebbre nyílik."]},{"n":144,"texts":["Az AI-gile egy kanbantábla egy embernek és sok MI-ügynöknek. A saját gépeden fut, és teljesen ingyenes. Projekteket adsz hozzá, és mindegyik kap egy lead-et meg egy kis csapatot. A lead-del csevegsz, kicsit Discord-módra, és elmeséled az ötletet; ő kártyákká és tervvé alakítja, aztán megvárja, hogy megnyomd a Go gombot. A csapat prioritási sorrendben halad a kártyákon, egy nyelvi modelleknek készült egyszerű parancssort használva. Mielőtt bármi visszajutna hozzád, egy MI-tesztelő végigköveti a lépéseket az alkalmazás egy másolatában, és képernyőképet csatol. A kész munka a változott fájlokkal és a diffel együtt a halmodra kerül. Elfogadod, vagy megjegyzést hagysz, a csapat pedig felébred és újra próbálkozik. Az egészből te csak azt látod, ami döntést kér. Kártyát csak te tehetsz a Kész oszlopba.","Nagyjából így néz ki egy nap az AI-gile-lal. Este hagysz pár megjegyzést: ez a gomb rossz helyen van, azt a listát rendezni kellene, lehetne sötét mód. Lefekszel aludni. Az ügynökök elolvassák a megjegyzéseket, elvégzik a módosításokat, letesztelik, és visszaadják neked. Ha kifogy a Teendő oszlop, az éjjeliőr feltölti a backlogból olyan kártyákkal, amelyekhez nem kell a válaszod. Reggel egyetlen rövid halom vár: néhány kérdés és néhány kipróbálnivaló, mindegyikhez lépések, amelyeket egy álmos ember is követ, és egy képernyőkép arról, hogy működik. Végigkattintod, elfogadod a jókat, a többit visszaküldöd. A tokenszámláló mutatja, mennyit fogyasztott mindez, a Token nélküli mód pedig a szűkös hetekre van. Nem kell közben ébren maradnod, és senki nem várja, hogy éjjel válaszolj. Aztán reggelizel, ebben az ügynökök még nem tudnak segíteni.","Először is: mi nem az AI-gile. Nem startup, nem eladó, és senki nem gyűjti az adataidat. Ingyenes tábla, ami a gépeden fut, fiók, követők és sütik nélkül. Ami viszont: egyetlen rendezett hely, ahol egyszerre látod az összes MI-s programozási projektet, ügynökcsapattal, amely a kártyákat viszi, és veled, aki a döntéseket hozod. Összevonja az összetartozó kártyákat, kijavítja a zavaros címeket, és figyeli, mennyire marad karcsú a kód. Nagyjából 120 nyelven beszél, a hollandtól és a flamandtól a kalózig és a klingonig. A barátok privátban és titkosítva üzenhetnek egymásnak. Nincs benne reklám, és senki nem hajt a felhasználókra. Rich és sok türelmes ügynök építette, többnyire önmagát használva. Zárt pre-alfában van, így néhol még nyers. Ha jókedvűnek hangzik, kérd szépen, és talán korán bejutsz."]}],"quips":{"1":"Egy szó. Merész. Talán túl merész is.","3":"Három szó. Már így őszintébb, mint a legtöbb termékoldal.","8":"Nyolc szó. Még mindig rövidebb egy stand-upnál.","21":"A hosszak egyébként story pointok. Hát persze, hogy azok.","55":"Ötvenöt szó. Amíg ezt olvastad, két kártya elkészült.","144":"Ez a hosszú. 233 nincs. Az ügynökök lefeküdtek aludni."}},"timeline":{"first-idea.name":"Az első ötlet","first-idea.line":"A legelső beszélgetés, még mielőtt egyetlen sor kód létezett volna.","first-board.name":"Az első tábla","first-board.line":"Egy tábla, amely a saját építését követi: kártyák, oszlopok, fogd és vidd, projektek.","team-roles.name":"Csapat és szerepek","team-roles.line":"Ügynökprofilok, csapatsablonok, terek és ki mit csinál.","install.name":"Telepítés és kiadások","install.line":"Egy zip, amit egy barát telepíthet, önfrissítés, csatornák és visszaállás.","usage-saver.name":"Használatspóroló","usage-saver.line":"Mérd, mibe kerülnek a futtatások, tartsd karcsún a kódot, spórolj a kereteddel.","friends.name":"Barátok és megosztás","friends.line":"Privát üzenetek, kevert továbbító, meghívók, szerepek és közös projektek.","languages.name":"Nyelvek","languages.line":"Minden képernyőszöveg egy nyelvi fájlban, elsőként hollandul és flamandul.","ai-tester.name":"MI-tesztelő","ai-tester.line":"Egy tesztelő előbb minden átadást ellenőriz, és megmutatja, mit látott.","website.name":"A weboldal","website.line":"Az aigile.lol, a teaser és ez az idővonal.","streaming.name":"Csevegés és streamelés","streaming.line":"Discord, Twitch, OBS, streamermód, GIF-ek és emojik.","no-ai.name":"MI nélküli kiadás","no-ai.line":"Tábla azoknak, akik MI nélkül programoznak, és nyilvános táblák.","night-watch.name":"Éjjeliőr","night-watch.line":"Egy őr és egy Scrum Master feladaton tartja a csapatokat, amíg alszol.","p-more.name":"Minden más","p-more.line":"Kisebb ötletek, amelyek még a sorukra várnak.","p-android.name":"Telefon és Android","p-android.line":"Érd el a táblád telefonról, aztán egy natív Android-alkalmazással.","p-release.name":"Alfa és tovább","p-release.line":"Zárt alfa, az éles oldal, aztán a béta.","p-languages.name":"Még több nyelv","p-languages.line":"Több mint száz nyelv, és elmerülős mód a tanulóknak.","p-engines.name":"Még több MI-motor","p-engines.line":"Válassz Claude-ot, Codexet vagy Geminit ügynökönként.","p-pro.name":"Profi gyakorlat","p-pro.line":"Kockázati címkék, merge-kapuk, incidenskártyák és védőkorlátok.","p-self.name":"Vigyázunk rád","p-self.line":"Fáradt mód, önmagadra figyelő emlékeztetők és a 4:20.","p-servers.name":"Szerverek és skálázás","p-servers.line":"Globális szerverbeállítások, szerepek és tervezés a növekedéshez.","p-livestream.name":"Streaming extrák","p-livestream.line":"Twitch-csevegés, egyéni emojik és nyilvános élő nézet."},"words":{"button":"📖 Fejlesztői szavak","h":"📖 Fejlesztői szavak magyarázata","intro":"A szavak, amelyeket a fejlesztők (és az MI-csapatok) használnak, érthetően.","search":"Szó keresése…","none":"Nincs ilyen szó.","close":"Bezárás","list":[{"id":"backlog","word":"Backlog","text":"Ötletek és munka, amelyek még nincsenek betervezve. Semmin sem dolgoznak ott, amíg át nem kerül a Teendő oszlopba."},{"id":"sprint","word":"Sprint","text":"Rövid munkaszakasz (gyakran egy-két hét) egy megbeszélt kártyahalmazzal, amit be kell fejezni.","also":["sprintek","sprintet","sprintben"]},{"id":"standup","word":"Stand-up","text":"Gyors egyeztetés: ki mit csinált, mit csinál ezután, és mi akadályozza.","also":["standup","stand-upok","standupok","stand-upot"]},{"id":"bug","word":"Bug","text":"Valami, ami nem úgy működik, ahogy kellene.","also":["bugok","bugot","bugja"]},{"id":"test","word":"Teszt","text":"Egy elkészült munka kipróbálása, hogy megnézd, azt csinálja-e, amit kértek, mielőtt elfogadod.","also":["tesztek","tesztet","tesztel","tesztelni","tesztelés","tesztelésre","tesztelendő","teszteld"],"noTip":1},{"id":"commit","word":"Commit","text":"A kód elmentett pillanatképe egy rövid megjegyzéssel arról, mi változott. Bármelyikhez bármikor visszatérhetsz.","also":["commitok","commitot"]},{"id":"push","word":"Push","text":"Az elmentett pillanatképek (commitok) feltöltése erről a gépről a GitHubra, hogy legyen róluk mentés, és mások is lássák."},{"id":"branch","word":"Branch","text":"A kód egy különálló munkavonala, hogy lehessen változtatni anélkül, hogy a fő verzióhoz hozzányúlnál.","also":["branchek","branchen"]},{"id":"merge","word":"Merge","text":"Egy branch változtatásainak visszaolvasztása a fő verzióba."},{"id":"repo","word":"Repo","text":"A projekt kódmappája és a commitok teljes története, ami általában a GitHubon is megvan.","also":["repository","repók"]},{"id":"refactor","word":"Refaktorálás","text":"A kód rendezése anélkül, hogy változna, amit csinál: kisebb fájlok, érthetőbb nevek, kevesebb ismétlés."},{"id":"deploy","word":"Deploy","text":"Egy új verzió élesítése, például egy szerveren, ahol az emberek használják."},{"id":"kanban","word":"Kanban","text":"Oszlopokból álló tábla (Teendő, Folyamatban, Kész), amelyen a kártyák balról jobbra haladnak, ahogy a munka halad."},{"id":"wip","word":"WIP-korlát","text":"Folyamatban lévő munka: legfeljebb ennyi kártya lehet egy oszlopban, hogy a csapat előbb befejezzen dolgokat, mielőtt újakba kezd.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Kérés, hogy egy branch változtatásait ellenőrizzék és olvasszák be a fő verzióba.","also":["PR"]},{"id":"hook","word":"Hook","text":"Egy kis parancs, amely magától lefut egy adott pillanatban, pl. amikor egy MI-munkamenet elindul, hogy a csapat meghallja a hozzászólásaidat.","also":["hookok","hookot"]},{"id":"token","word":"Token","text":"Az egység, amiben az MI-használatot számoljuk: nagyjából néhány betűnyi elolvasott vagy megírt szöveg. Minél kevesebb token, annál több marad a csomagodból.","also":["tokenek","tokent"]},{"id":"agent","word":"Ügynök","text":"Egy MI, amely önállóan dolgozik egy feladaton: olvassa a kódot, módosít, ellenőrzéseket futtat, és jelent.","also":["ügynökök","ügynököt","agent","agentek"]}]}};
